begin;

-- LC editorial pilot: Lógica de Programação Básica / módulo 1
-- Substitui conteúdo repetitivo por narrativa editorial específica de cada competência.

update nexora.lessons
set objective='Diferenciar programação de linguagem de programação e reconhecer um programa como uma sequência precisa que recebe dados, aplica regras e produz um resultado observável.', estimated_minutes=22, content='[{"type":"story","title":"Você já executa algoritmos sem perceber","body":"Imagine que uma loja precise calcular o desconto de cada pedido. Uma pessoa poderia olhar o valor da compra, consultar a regra da promoção, calcular o desconto e informar o total. Um programa faz essencialmente a mesma coisa, com uma diferença decisiva: as instruções precisam ser suficientemente precisas para que uma máquina consiga executá-las sem perguntar o que você quis dizer.\n\nÉ por isso que aprender programação não começa decorando comandos. Começa aprendendo a transformar uma intenção — “calcule o desconto” — em passos claros, dados identificáveis e um resultado que possa ser conferido."},{"type":"concept","title":"Programar é descrever uma solução executável","body":"Programar é construir instruções para que um computador realize uma tarefa. Essas instruções podem receber dados, tomar decisões, repetir ações, fazer cálculos e produzir resultados. O código é a forma escrita dessa solução em uma linguagem de programação.\n\nPython, JavaScript e Java são linguagens diferentes, mas a lógica pode ser a mesma. Se o problema é calcular a média de duas notas, qualquer linguagem precisará receber duas notas, somá-las, dividir o total por dois e apresentar o resultado. A sintaxe muda; a ideia permanece.\n\nEssa distinção é importante porque um iniciante pode memorizar `if`, `for` ou `print` e ainda não saber resolver um problema. A competência central é conseguir explicar o que precisa acontecer antes de escolher os comandos."},{"type":"comparison","title":"Problema, algoritmo, linguagem e código não são a mesma coisa","body":"O problema descreve o que precisa ser resolvido. O algoritmo organiza a solução em passos. A linguagem fornece regras e palavras para expressar esses passos. O código é a implementação concreta escrita nessa linguagem.","items":["Problema: calcular o valor final de uma compra com desconto.","Algoritmo: ler o valor, verificar a faixa de desconto, calcular e mostrar o total.","Linguagem: JavaScript, Python, Java ou outra.","Código: as instruções específicas escritas na linguagem escolhida."]},{"type":"example","title":"Um programa antes do código","body":"Considere a regra: compras de R$ 100 ou mais recebem 10% de desconto.\n\nEntrada: valor da compra.\nProcessamento: verificar se o valor é pelo menos 100; quando for, calcular 10% e subtrair do total.\nSaída: valor final.\n\nPara uma compra de R$ 150, esperamos R$ 135. Para uma compra de R$ 80, esperamos R$ 80. Observe que já conseguimos discutir se a solução está correta sem escrever uma única linha de código."},{"type":"guided","title":"Antes de seguir, separe lógica de linguagem","question":"Qual alternativa descreve melhor o que permanece igual ao implementar a mesma solução em Python e JavaScript?","options":["Os comandos e a pontuação usados no código.","A lógica de entrada, regra e saída da solução.","O nome obrigatório de todas as variáveis.","A forma exata de mostrar mensagens na tela."],"answer":1,"feedback":"Correto. A sintaxe pode mudar, mas a lógica que transforma entrada em resultado continua sendo a mesma.","feedback_incorrect":"A linguagem muda a forma de escrever. Procure a alternativa que descreve a solução independentemente da sintaxe."},{"type":"professional_context","title":"Por que profissionais começam pelo problema","body":"Em projetos reais, o pedido quase nunca chega como código. Ele chega como necessidade: “bloqueie pedidos sem estoque”, “calcule comissão”, “ordene atendimentos por prioridade”. O trabalho de programação começa ao esclarecer dados, regras e resultado esperado. Quanto melhor essa etapa, menos retrabalho aparece depois."},{"type":"recap","items":["Programação é solução executável, não memorização de comandos.","Problema, algoritmo, linguagem e código representam etapas diferentes.","A mesma lógica pode ser implementada em linguagens diferentes.","Uma solução boa tem entrada, regra e resultado que possam ser conferidos."]}]'::jsonb, lab_type='checkpoint', lab_config='{"module":"Pensar antes de programar","concept":"Diferenciar programação de linguagem de programação e reconhecer um programa como uma sequência precisa que recebe dados, aplica regras e produz um resultado observável.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma empresa pede: “calcule a comissão de 5% sobre vendas concluídas”. Qual é o melhor primeiro passo antes de escolher uma linguagem?","options":["Pesquisar qual linguagem tem a função comissão().","Definir quais vendas entram no cálculo, a regra de 5% e qual resultado deve ser produzido.","Criar a tela do sistema para depois descobrir a regra.","Escolher nomes de variáveis e só então perguntar como funciona a comissão."],"answer":1,"feedback":"Correto. Programar começa modelando o problema: dados, regra e resultado.","feedback_incorrect":"A linguagem vem depois. Primeiro precisamos transformar a necessidade em uma regra que possa ser executada e testada."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='a6b6f783-10ee-491a-85b9-48b6d5618150';

update nexora.lessons
set objective='Transformar uma situação cotidiana em um problema computacional identificando entradas, processamento, saída e pelo menos um caso de teste.', estimated_minutes=22, content='[{"type":"story","title":"Uma regra vaga ainda não é um problema computacional","body":"“Cobrar frete corretamente” parece uma tarefa simples, mas ainda é vaga demais para um programa. Qual dado determina o frete? Existe uma faixa de gratuidade? O endereço interfere? Qual valor deve ser mostrado?\n\nPara a máquina, essas perguntas não são detalhes. Elas definem o problema. Modelar um problema computacional significa deixar claro o que recebemos, o que fazemos com esses dados e qual resultado precisamos produzir."},{"type":"concept","title":"Entrada → processamento → saída","body":"A entrada reúne os dados necessários para resolver a tarefa. O processamento representa as regras, cálculos ou decisões aplicadas. A saída é o resultado observável depois que as regras foram executadas.\n\nEsse modelo é simples, mas poderoso. Ele ajuda a transformar pedidos genéricos em algo testável. Se você não sabe dizer qual é a saída esperada, ainda não sabe como provar que sua solução funciona."},{"type":"mechanics","title":"Modele antes de escrever passos","body":"Use quatro perguntas como filtro antes de programar:","items":["Que informação o sistema precisa receber?","Que regras ou transformações serão aplicadas?","Que resultado precisa ser entregue?","Que exemplo concreto prova que a regra funciona?"]},{"type":"example","title":"Frete de uma loja virtual","body":"Regra: pedidos a partir de R$ 200 têm frete grátis; abaixo disso, o frete custa R$ 20.\n\nEntrada: valor do pedido.\nProcessamento: comparar o valor com 200 e escolher uma das duas tarifas.\nSaída: valor do frete.\n\nCasos de teste: R$ 199 → frete R$ 20; R$ 200 → frete R$ 0; R$ 350 → frete R$ 0. O caso R$ 200 é especialmente importante porque está exatamente no limite da regra."},{"type":"mistake","title":"Não confunda dado com regra","body":"“Cliente premium” pode ser uma entrada se essa informação já vier cadastrada. “Cliente premium recebe 15% de desconto” é uma regra de processamento. Misturar essas duas coisas torna a solução difícil de explicar e de testar."},{"type":"professional_context","title":"Esse modelo aparece em sistemas inteiros","body":"Formulários, APIs, planilhas, automações e aplicações web seguem o mesmo raciocínio. Uma API recebe uma requisição, processa dados e devolve uma resposta. Uma planilha recebe valores, aplica fórmulas e produz resultados. Pensar em entrada, processamento e saída cria uma ponte entre lógica de programação e ferramentas que você aprenderá depois."},{"type":"recap","items":["Entrada é o dado necessário para executar a solução.","Processamento é a regra aplicada aos dados.","Saída é o resultado que pode ser observado e testado.","Casos concretos, principalmente nos limites, tornam a regra verificável."]}]'::jsonb, lab_type='logic', lab_config='{"module":"Pensar antes de programar","concept":"Transformar uma situação cotidiana em um problema computacional identificando entradas, processamento, saída e pelo menos um caso de teste.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Monte a sequência correta para uma solução verificável.","options":["Entrada → regra → saída → teste","Teste → saída → interface → código"],"answer":0,"feedback":"Correto.","feedback_incorrect":"Comece entendendo os dados; depois aplique a regra, observe a saída e teste o resultado."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='bd010871-3109-4507-bb41-03ab62fcda83';

update nexora.lessons
set objective='Construir e avaliar algoritmos simples verificando ordem, clareza, término e resultado esperado antes de pensar em sintaxe.', estimated_minutes=23, content='[{"type":"concept","title":"Algoritmo é um procedimento que pode ser seguido","body":"Um algoritmo é uma sequência finita e ordenada de passos para transformar uma situação inicial em um resultado. “Finita” significa que o procedimento precisa terminar. “Ordenada” significa que a posição dos passos importa. “Executável” significa que cada instrução precisa dizer algo que realmente possa ser feito.\n\nA palavra pode parecer técnica, mas a ideia é cotidiana: instruções de montagem, receita, rota e checklist são procedimentos. Em programação, o rigor é maior porque a máquina não preenche lacunas usando bom senso."},{"type":"example","title":"Compare duas instruções para a mesma tarefa","body":"Versão vaga: “Pegue duas notas e faça o necessário para mostrar a média.”\n\nVersão executável:\n1. Receber a primeira nota.\n2. Receber a segunda nota.\n3. Somar as duas notas.\n4. Dividir a soma por 2.\n5. Mostrar a média.\n\nA segunda versão permite simular cada etapa e identificar exatamente onde um erro aconteceu."},{"type":"mechanics","title":"Quatro perguntas para revisar um algoritmo","items":["A ordem dos passos produz o resultado correto?","Cada instrução descreve uma ação sem depender de adivinhação?","O procedimento termina para todas as entradas previstas?","Consigo prever uma saída e conferir se ela foi alcançada?"]},{"type":"comparison","title":"Algoritmo não é código","body":"O algoritmo expressa a solução. O código traduz essa solução para uma linguagem específica. Você pode escrever um algoritmo em linguagem natural, pseudocódigo, fluxograma ou outra representação. Só depois ele precisa virar código executável."},{"type":"guided","title":"A ordem muda o resultado","question":"Para calcular o preço final com 10% de desconto, qual sequência está correta?","options":["Receber preço → calcular 10% → subtrair o desconto → mostrar resultado.","Mostrar resultado → receber preço → subtrair 10 → calcular porcentagem.","Calcular 10% sem receber preço → mostrar resultado → receber preço.","Receber preço → mostrar preço original → encerrar sem aplicar a regra."],"answer":0,"feedback":"Correto. Cada passo produz a informação necessária para o passo seguinte.","feedback_incorrect":"Observe a dependência entre as etapas: primeiro precisamos do preço; depois calculamos e aplicamos o desconto."},{"type":"mistake","title":"Instruções vagas escondem problemas","body":"Expressões como “processe os dados”, “faça a validação” ou “resolva o cálculo” podem servir como nomes de etapas em um planejamento, mas não são suficientes quando queremos testar a lógica. Ao detalhar um algoritmo, transforme cada uma delas em ações observáveis."},{"type":"recap","items":["Algoritmos têm passos claros, ordenados e finitos.","A ordem pode alterar completamente o resultado.","Um algoritmo pode ser descrito antes de escolher uma linguagem.","Se um passo não pode ser executado ou verificado, ele precisa ser refinado."]}]'::jsonb, lab_type='checkpoint', lab_config='{"module":"Pensar antes de programar","concept":"Construir e avaliar algoritmos simples verificando ordem, clareza, término e resultado esperado antes de pensar em sintaxe.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Qual instrução torna um algoritmo mais verificável?","options":["“Processe os dados corretamente.”","“Se a idade for menor que 18, marcar o cadastro como ‘menor de idade’.”","“Faça o que for necessário.”","“Melhore o resultado quando possível.”"],"answer":1,"feedback":"Correto. A instrução define uma condição e um efeito observável.","feedback_incorrect":"Procure uma instrução que diga exatamente quando agir e qual resultado produzir."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='8916b492-35d6-433f-b3de-8fbea8059e2f';

update nexora.lessons
set objective='Decompor um problema maior em subtarefas com responsabilidades, entradas e resultados claros, reduzindo a complexidade da solução.', estimated_minutes=22, content='[{"type":"story","title":"“Criar um cadastro” é grande demais para ser uma única tarefa","body":"Um cadastro aparentemente simples pode envolver receber dados, validar campos, verificar duplicidade, salvar informações, informar erros e confirmar o sucesso. Se tratarmos tudo como um bloco único, qualquer falha parece estar “no cadastro”.\n\nDecompor significa transformar esse problema grande em partes menores que possam ser entendidas, testadas e corrigidas separadamente."},{"type":"concept","title":"Divida pelo que cada parte precisa resolver","body":"Uma boa decomposição não é apenas cortar uma tarefa em pedaços arbitrários. Cada subtarefa deve ter uma responsabilidade clara. Idealmente, você consegue dizer o que ela recebe, o que faz e o que entrega.\n\nIsso reduz a quantidade de coisas que precisamos pensar ao mesmo tempo. Também facilita reutilizar partes da solução: uma rotina de validação de CPF, por exemplo, pode ser usada em mais de um fluxo."},{"type":"example","title":"Decompondo um cadastro de aluno","items":["Coletar dados: receber nome, e-mail e data de nascimento.","Validar: conferir campos obrigatórios e formatos.","Verificar duplicidade: descobrir se o e-mail já está cadastrado.","Salvar: registrar os dados aprovados.","Confirmar: mostrar ao usuário que o cadastro foi concluído."]},{"type":"comparison","title":"Decomposição boa × decomposição superficial","body":"“Frontend, backend e banco” pode ser uma divisão útil para organizar equipes, mas ainda não explica a lógica do cadastro. Para raciocínio computacional, é mais útil separar responsabilidades funcionais: validar, verificar duplicidade, salvar e confirmar. A divisão precisa ajudar a resolver e testar o problema."},{"type":"guided","title":"Escolha a divisão que ajuda a testar","question":"Qual decomposição é mais útil para um sistema que calcula a média e informa a situação do aluno?","options":["Tela bonita → botão azul → animação → relatório.","Receber notas → validar notas → calcular média → classificar situação → mostrar resultado.","Programar tudo → testar no fim.","Criar banco → criar logo → escolher fonte → calcular média."],"answer":1,"feedback":"Correto. As partes seguem responsabilidades funcionais e podem ser testadas separadamente.","feedback_incorrect":"Procure uma divisão baseada no fluxo real do problema, não em detalhes visuais ou tecnologias."},{"type":"professional_context","title":"Decomposição também melhora manutenção","body":"Quando um sistema cresce, funções e módulos bem separados permitem alterar uma regra sem reescrever tudo. Se a regra de aprovação mudar, queremos localizar a etapa de classificação, não procurar a condição escondida em um bloco enorme."},{"type":"recap","items":["Decompor é reduzir um problema grande a responsabilidades menores.","Cada parte deve ter uma função clara na solução.","Partes menores são mais fáceis de testar, corrigir e reutilizar.","A decomposição deve seguir o problema, não apenas as tecnologias usadas."]}]'::jsonb, lab_type='checkpoint', lab_config='{"module":"Pensar antes de programar","concept":"Decompor um problema maior em subtarefas com responsabilidades, entradas e resultados claros, reduzindo a complexidade da solução.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Um sistema de pedidos precisa validar itens, calcular total, aplicar desconto e gerar confirmação. Qual organização é mais saudável?","options":["Um único passo chamado “processar pedido”.","Quatro etapas separadas, cada uma com responsabilidade e resultado definido.","Começar pela tela e decidir as regras durante a implementação.","Misturar validação, desconto e confirmação para reduzir a quantidade de etapas."],"answer":1,"feedback":"Correto. Responsabilidades separadas tornam a solução mais compreensível e testável.","feedback_incorrect":"Menos etapas nem sempre significa menos complexidade. Procure a solução que separa responsabilidades."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='14c63af7-5a03-46ea-a5cb-d62592b14e4d';

update nexora.lessons
set objective='Reconhecer padrões estruturais entre problemas diferentes e reutilizar estratégias de solução sem generalizar situações que apenas parecem semelhantes.', estimated_minutes=21, content='[{"type":"story","title":"Problemas diferentes podem esconder a mesma estrutura","body":"Somar os valores de uma compra e somar as horas trabalhadas na semana parecem tarefas de áreas completamente diferentes. Porém, na lógica, ambas podem seguir o mesmo padrão: começar com um total, percorrer valores e acumular cada item.\n\nReconhecer padrões significa enxergar essa estrutura comum. Isso permite aproveitar uma estratégia conhecida em um novo problema."},{"type":"concept","title":"Procure relações, não palavras iguais","body":"O reconhecimento de padrões compara como os dados se comportam e quais regras são aplicadas. Dois problemas não precisam usar os mesmos nomes. “Vendas”, “horas” e “pontos” podem compartilhar a lógica de acumulação.\n\nPor outro lado, aparência semelhante não garante a mesma solução. Calcular a maior nota e calcular a média usam a mesma lista de notas, mas exigem operações diferentes. O padrão precisa existir na estrutura do processamento."},{"type":"comparison","title":"Três padrões que aparecerão muitas vezes","items":["Acumulação: combinar vários valores em um total.","Contagem: aumentar um contador quando uma condição acontece.","Busca: percorrer dados até encontrar algo que satisfaça um critério."]},{"type":"example","title":"O padrão de acumulação","body":"Para somar [20, 15, 30], começamos com total = 0. Depois: total = 0 + 20; total = 20 + 15; total = 35 + 30. Resultado: 65.\n\nA mesma estrutura pode somar vendas de um dia, quilômetros percorridos ou quantidade de itens, desde que a regra seja combinar cada valor ao total."},{"type":"guided","title":"Identifique o padrão","question":"Qual situação usa mais claramente o mesmo padrão de acumulação do exemplo?","options":["Descobrir se uma senha tem pelo menos 8 caracteres.","Somar o valor de todas as parcelas pagas por um cliente.","Verificar se uma idade é maior ou igual a 18.","Escolher entre frete grátis ou pago."],"answer":1,"feedback":"Correto. A tarefa combina vários valores em um total acumulado.","feedback_incorrect":"Procure uma situação em que vários valores são combinados progressivamente em um único total."},{"type":"mistake","title":"Não force reutilização","body":"Generalizar cedo demais pode tornar a solução confusa. Antes de reutilizar uma estratégia, pergunte se entradas, transformação e objetivo realmente seguem a mesma estrutura. Sem isso, o “padrão” é apenas uma semelhança superficial."},{"type":"recap","items":["Padrões são estruturas de solução que se repetem em contextos diferentes.","Nomes diferentes podem esconder a mesma lógica.","Acumulação, contagem e busca são padrões comuns.","Reutilize uma estratégia apenas quando a estrutura do problema realmente for semelhante."]}]'::jsonb, lab_type='checkpoint', lab_config='{"module":"Pensar antes de programar","concept":"Reconhecer padrões estruturais entre problemas diferentes e reutilizar estratégias de solução sem generalizar situações que apenas parecem semelhantes.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Dois problemas usam listas. Um pede a soma dos valores e outro pede o primeiro valor acima de 100. O que podemos concluir?","options":["São o mesmo padrão porque ambos usam listas.","São padrões diferentes: um é acumulação e o outro é busca.","Devem usar exatamente o mesmo algoritmo.","A diferença só existe por causa do nome das variáveis."],"answer":1,"feedback":"Correto. O tipo de dado pode ser igual, mas a intenção do processamento é diferente.","feedback_incorrect":"Compare o que cada solução precisa produzir, não apenas o tipo de entrada."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='b6fd0e92-b96c-45d9-a3b2-948c919098a1';

update nexora.lessons
set objective='Usar abstração para destacar dados e regras relevantes de uma solução, escondendo detalhes que não precisam participar do raciocínio naquele momento.', estimated_minutes=21, content='[{"type":"story","title":"Você usa abstrações todos os dias","body":"Ao usar um aplicativo de mapas, você pede uma rota sem precisar pensar em satélites, algoritmos de geolocalização ou no formato interno dos dados. O aplicativo expõe o que importa para sua tarefa: origem, destino e rota.\n\nNa programação, abstração segue a mesma ideia. Criamos representações que mostram o necessário e escondem detalhes que já podem ser tratados internamente."},{"type":"concept","title":"Abstrair é escolher o nível certo de detalhe","body":"Abstração não significa ignorar informação importante. Significa decidir quais detalhes precisam estar visíveis para resolver o problema atual.\n\nAo calcular frete, talvez importem valor do pedido, destino e tipo de entrega. A cor do botão “Comprar” não participa dessa regra. Separar regra de negócio de detalhes de interface deixa o raciocínio mais claro.\n\nMais tarde, funções, objetos, APIs e módulos serão formas práticas de construir abstrações: cada componente oferece uma interface simples e esconde parte da implementação."},{"type":"example","title":"Uma função como caixa-preta útil","body":"Imagine `calcularFrete(valorPedido, cep) → valorFrete`. Quem usa essa função precisa saber quais dados fornecer e qual resultado receberá. A fórmula, as tabelas de região e outras regras podem ficar dentro dela.\n\nIsso permite raciocinar sobre “calcular frete” como uma única etapa quando o detalhe interno não é relevante para o problema maior."},{"type":"comparison","title":"O que manter visível?","items":["Mantenha: entradas necessárias, regra relevante, saída e condições importantes.","Pode esconder: detalhes internos já resolvidos, estruturas auxiliares e implementação que não muda o contrato.","Nunca esconda: informação necessária para entender por que o resultado está correto ou errado."]},{"type":"guided","title":"Escolha a abstração útil","question":"Para calcular aprovação escolar, qual conjunto contém apenas informações relevantes para a regra?","options":["Nota, frequência e critérios mínimos de aprovação.","Cor do portal, tamanho do logo e nota.","Nome da fonte, animação e frequência.","Modelo do celular, nota e cor do botão."],"answer":0,"feedback":"Correto. Esses dados participam diretamente da decisão de aprovação.","feedback_incorrect":"Abstração mantém o que influencia a regra e remove detalhes que não alteram o resultado."},{"type":"professional_context","title":"Boas abstrações reduzem dependências","body":"Quando diferentes partes de um sistema dependem apenas de um contrato claro, mudanças internas ficam mais seguras. Uma API pode trocar a forma de consultar o banco sem obrigar o aplicativo inteiro a mudar, desde que continue recebendo e devolvendo os mesmos dados esperados."},{"type":"recap","items":["Abstração mostra o que importa no nível atual do problema.","Esconder detalhes é útil quando o contrato continua claro.","Regra de negócio e detalhe visual geralmente pertencem a níveis diferentes.","Uma boa abstração reduz complexidade sem esconder informação necessária para validar a solução."]}]'::jsonb, lab_type='checkpoint', lab_config='{"module":"Pensar antes de programar","concept":"Usar abstração para destacar dados e regras relevantes de uma solução, escondendo detalhes que não precisam participar do raciocínio naquele momento.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma função `calcularMedia(notas)` é usada em várias telas. Qual informação precisa fazer parte do contrato da abstração?","options":["A cor do botão que chama a função.","Que dados ela recebe e que resultado devolve.","O nome de cada desenvolvedor que alterou a função.","A posição da função dentro do arquivo."],"answer":1,"feedback":"Correto. Entradas e saída definem o contrato que outras partes precisam conhecer.","feedback_incorrect":"Quem usa uma abstração precisa conhecer o que fornecer e o que receber, não os detalhes internos ou visuais."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='766f57ff-52a0-4c40-8588-9bd2fb9359f8';

update nexora.lessons
set objective='Executar um teste de mesa acompanhando valores passo a passo e escolher casos normais, limites e de erro capazes de revelar falhas na lógica.', estimated_minutes=24, content='[{"type":"story","title":"O erro costuma morar exatamente no limite","body":"Considere a regra: “frete grátis para pedidos a partir de R$ 200”. Um teste com R$ 350 passa. Um teste com R$ 50 também. Ainda assim, a implementação pode estar errada se usar `>` em vez de `>=`. O pedido de exatamente R$ 200 revelaria a falha.\n\nTeste de mesa é a prática de simular manualmente a execução usando valores escolhidos de propósito. Em vez de confiar que a lógica “parece certa”, acompanhamos o que acontece em cada etapa."},{"type":"concept","title":"Simule entradas e registre estados","body":"Em um teste de mesa, escolhemos uma entrada, percorremos o algoritmo na mesma ordem em que ele seria executado e anotamos valores intermediários e resultado final. Depois comparamos com o que esperávamos.\n\nEsse processo ajuda a encontrar erros antes de existir uma aplicação completa. Ele também força uma habilidade importante: prever o comportamento da solução antes de executá-la."},{"type":"mechanics","title":"Escolha casos que pressionem a regra","items":["Caso normal: um valor comum dentro do comportamento esperado.","Caso de limite: valor exatamente na fronteira da condição, e quando útil logo abaixo e logo acima.","Caso inválido ou inesperado: dado vazio, negativo ou fora do domínio, quando a regra prevê tratamento.","Resultado esperado: escreva antes de simular para não ajustar a expectativa depois de ver a saída."]},{"type":"example","title":"Tabela de teste — frete grátis em R$ 200","body":"Entrada R$ 199 → esperado: frete R$ 20.\nEntrada R$ 200 → esperado: frete R$ 0.\nEntrada R$ 201 → esperado: frete R$ 0.\n\nSe o algoritmo produzir R$ 20 para o pedido de R$ 200, sabemos que a fronteira foi implementada incorretamente. O teste não apenas diz que algo falhou; ele aponta onde investigar."},{"type":"comparison","title":"Testar não é experimentar valores aleatórios","body":"Testes aleatórios podem encontrar problemas, mas um bom conjunto de casos nasce da regra. Se existe uma fronteira, testamos a fronteira. Se existe divisão, pensamos em zero. Se uma lista pode estar vazia, testamos a lista vazia. Cada caso deve ter uma razão para existir."},{"type":"guided","title":"Escolha o conjunto mais informativo","question":"Uma promoção vale para idades de 18 anos ou mais. Qual conjunto testa melhor a fronteira da regra?","options":["18, 30 e 50.","17, 18 e 19.","5, 10 e 15.","30, 40 e 50."],"answer":1,"feedback":"Correto. Logo abaixo, exatamente no limite e logo acima revelam erros de comparação.","feedback_incorrect":"Quando existe uma fronteira, teste o valor imediatamente abaixo, o próprio limite e o valor imediatamente acima."},{"type":"mastery","title":"Você conclui o módulo quando consegue pensar assim","items":["Antes do código, consigo definir dados, regras e resultado.","Consigo organizar uma solução em passos claros e finitos.","Se o problema cresce, consigo separá-lo em responsabilidades menores.","Consigo reconhecer padrões sem forçar semelhanças.","Consigo esconder detalhes sem perder o contrato da solução.","Consigo prever resultados e testar limites de forma intencional."]},{"type":"recap","items":["Teste de mesa simula a execução passo a passo.","O resultado esperado deve ser definido antes da simulação.","Casos de limite revelam erros que casos confortáveis não mostram.","Testar bem significa escolher entradas com intenção, não apenas aumentar a quantidade de tentativas."]}]'::jsonb, lab_type='checkpoint', lab_config='{"module":"Pensar antes de programar","concept":"Executar um teste de mesa acompanhando valores passo a passo e escolher casos normais, limites e de erro capazes de revelar falhas na lógica.","pedagogy":"narrativa-contextual-pratica-validacao","checkpoint":{"question":"Uma regra aceita notas entre 0 e 10, inclusive. Qual conjunto oferece a melhor cobertura inicial?","options":["5 e 6.","0, 10, -1 e 11.","7, 8 e 9.","Somente 10."],"answer":1,"feedback":"Correto. O conjunto cobre os dois limites válidos e valores imediatamente fora do domínio.","feedback_incorrect":"Procure casos que exercitem os limites da regra e também entradas inválidas próximas a eles."},"source_policy":"Conteúdo editorial LC revisado para clareza conceitual, aplicação e validação.","editorial_version":"lc-editorial-pilot-2026.08"}'::jsonb
where id='c421d255-b63f-4932-a1d7-a61ceafe037d';

update nexora.questions set position=1, prompt='Uma empresa pede: “calcule 5% de comissão sobre vendas concluídas”. O que deve ser definido antes de escolher a linguagem?', options='[{"id":"a","label":"Os comandos específicos da linguagem."},{"id":"b","label":"Quais vendas entram, a regra de 5% e qual saída deve ser produzida."},{"id":"c","label":"O layout da tela final."},{"id":"d","label":"O nome das variáveis antes de entender a regra."}]'::jsonb, correct_answer='{"option_id":"b"}'::jsonb, feedback_correct='Correto. A lógica do problema vem antes da sintaxe.', feedback_incorrect='Revise a diferença entre modelar a solução e implementá-la em uma linguagem.', difficulty=1 where id='23686851-dec3-4a28-a484-368a78f34288';
update nexora.questions set position=2, prompt='Um sistema recebe o valor do pedido e devolve o frete. Qual alternativa identifica corretamente entrada e saída?', options='[{"id":"a","label":"Entrada: valor do pedido; saída: valor do frete."},{"id":"b","label":"Entrada: valor do frete; saída: regra de desconto."},{"id":"c","label":"Entrada: código-fonte; saída: valor do pedido."},{"id":"d","label":"Entrada: tela; saída: linguagem de programação."}]'::jsonb, correct_answer='{"option_id":"a"}'::jsonb, feedback_correct='Correto. O dado recebido alimenta a regra; o frete é o resultado observável.', feedback_incorrect='Procure o dado que chega ao processamento e o resultado que a solução precisa entregar.', difficulty=1 where id='c6aa55d0-b3dd-44cf-81eb-0edf88980a14';
update nexora.questions set position=3, prompt='Qual sequência representa melhor um algoritmo para calcular a média de duas notas?', options='[{"id":"a","label":"Mostrar média → receber notas → somar."},{"id":"b","label":"Receber duas notas → somar → dividir por 2 → mostrar média."},{"id":"c","label":"Escolher Python → criar tela → perguntar as notas."},{"id":"d","label":"Receber uma nota → mostrar resultado → receber a segunda."}]'::jsonb, correct_answer='{"option_id":"b"}'::jsonb, feedback_correct='Correto. A ordem produz as informações necessárias para cada etapa seguinte.', feedback_incorrect='Revise dependência e ordem dos passos do algoritmo.', difficulty=2 where id='8b17999c-caa5-4e41-8aa2-255651efcfec';
update nexora.questions set position=4, prompt='Qual decomposição é mais útil para um cadastro de usuário?', options='[{"id":"a","label":"Coletar dados → validar → verificar duplicidade → salvar → confirmar."},{"id":"b","label":"Frontend → azul → logo → banco."},{"id":"c","label":"Processar cadastro em um único passo."},{"id":"d","label":"Escolher tecnologia → publicar → descobrir regras."}]'::jsonb, correct_answer='{"option_id":"a"}'::jsonb, feedback_correct='Correto. Cada etapa tem uma responsabilidade funcional clara.', feedback_incorrect='Procure uma divisão que ajude a entender e testar o fluxo do problema.', difficulty=2 where id='566525ae-e03c-4e88-bf47-31d04e9eca1d';
update nexora.questions set position=5, prompt='Somar vendas e somar horas trabalhadas podem usar a mesma estratégia. Qual padrão está sendo reconhecido?', options='[{"id":"a","label":"Acumulação de vários valores em um total."},{"id":"b","label":"Busca do primeiro item válido."},{"id":"c","label":"Decisão binária sem repetição."},{"id":"d","label":"Validação de senha."}]'::jsonb, correct_answer='{"option_id":"a"}'::jsonb, feedback_correct='Correto. Contextos diferentes podem compartilhar a estrutura de acumulação.', feedback_incorrect='Compare a transformação realizada nos dados, não os nomes usados.', difficulty=2 where id='830321ea-61f8-4587-a46d-29098de3ed42';
update nexora.questions set position=6, prompt='Uma função calcularFrete(valor, cep) esconde suas regras internas. O que outras partes do sistema precisam conhecer?', options='[{"id":"a","label":"Todas as variáveis internas."},{"id":"b","label":"A posição exata da função no arquivo."},{"id":"c","label":"Quais dados fornecer e qual resultado a função devolve."},{"id":"d","label":"A cor do botão que chama a função."}]'::jsonb, correct_answer='{"option_id":"c"}'::jsonb, feedback_correct='Correto. Uma abstração útil mantém claro o contrato de entrada e saída.', feedback_incorrect='Revise o que precisa continuar visível quando detalhes internos são escondidos.', difficulty=3 where id='3f1bbc2e-4442-45cf-be9d-7fc7395aebbd';

insert into nexora.questions(id,assessment_id,prompt,question_type,options,correct_answer,feedback_correct,feedback_incorrect,difficulty,position)
select gen_random_uuid(),'190e0431-c163-4be5-82e6-2cfd0d853d3b','Uma regra dá frete grátis para pedidos a partir de R$ 200. Qual conjunto de teste pressiona melhor a fronteira?','multiple_choice','[{"id":"a","label":"R$ 50, R$ 100 e R$ 150."},{"id":"b","label":"R$ 199, R$ 200 e R$ 201."},{"id":"c","label":"R$ 300 e R$ 400."},{"id":"d","label":"Somente R$ 200."}]'::jsonb,'{"option_id":"b"}'::jsonb,'Correto. Abaixo, no limite e acima da fronteira revelam erros de comparação.','Procure valores construídos em torno do limite da regra.',2,7
where not exists(select 1 from nexora.questions where assessment_id='190e0431-c163-4be5-82e6-2cfd0d853d3b' and position=7);

update nexora.assessments set title='Checkpoint aplicado — Pensar antes de programar', pass_score=70, max_attempts=3 where id='190e0431-c163-4be5-82e6-2cfd0d853d3b';

update nexora.learning_resources set title='Apostila LC — Pensar antes de programar', summary='Revisão editorial do módulo com conexões entre conceitos, mapa mental e exercícios.', content='{"editorial_version":"lc-editorial-pilot-2026.08","pedagogy":"leitura de revisão e conexão entre conceitos","sections":[{"title":"1. Programar é transformar intenção em instruções","body":"Programação começa quando uma necessidade é descrita de forma suficientemente precisa para ser executada. Antes da sintaxe, identifique o problema, os dados disponíveis, as regras e o resultado esperado.","items":["Problema é a necessidade a resolver.","Algoritmo organiza a solução.","Linguagem fornece a sintaxe.","Código é a implementação concreta."]},{"title":"2. Modele entrada, processamento e saída","body":"Uma solução verificável deixa claro o que recebe, o que faz e o que entrega. Use casos concretos para confirmar a regra, principalmente nas fronteiras."},{"title":"3. Algoritmos precisam ser claros, ordenados e finitos","body":"Cada passo deve representar uma ação possível. A ordem deve fazer sentido e o processo precisa terminar. Um bom algoritmo pode ser simulado antes de virar código."},{"title":"4. Decomposição reduz complexidade","body":"Separe problemas grandes em responsabilidades menores, cada uma com função clara. Isso melhora compreensão, teste, manutenção e reutilização."},{"title":"5. Padrões ajudam a reutilizar raciocínio","body":"Observe estruturas que se repetem entre problemas: acumular valores, contar ocorrências, buscar itens ou escolher caminhos. Reutilize estratégias apenas quando a estrutura realmente for semelhante."},{"title":"6. Abstração escolhe o nível certo de detalhe","body":"Mantenha visíveis entradas, regras e saídas relevantes. Detalhes internos podem ser escondidos quando o contrato da solução continua claro."},{"title":"7. Teste de mesa valida a lógica antes do código","body":"Simule a execução com casos normais, limites e entradas inesperadas. Escreva o resultado esperado antes de seguir os passos e compare previsão com resultado."},{"title":"Mapa mental do módulo","items":["Entenda o problema.","Defina entrada e saída.","Organize um algoritmo.","Decomponha quando necessário.","Reconheça padrões úteis.","Abstraia detalhes irrelevantes.","Teste casos normais e limites."]},{"title":"Exercícios de revisão","items":["Modele entrada, processamento e saída para uma regra de desconto progressivo.","Escreva um algoritmo em linguagem natural para calcular média de três valores.","Decomponha um fluxo de agendamento em pelo menos quatro responsabilidades.","Encontre um exemplo de acumulação e outro de busca em situações cotidianas.","Crie três casos de teste para uma regra de idade mínima de 18 anos."]}]}'::jsonb where id='2985182f-7a50-4b0f-833a-3d9c379791ee';
update nexora.learning_resources set title='Guia de raciocínio — Pensar antes de programar', summary='Checklist prático para modelar problemas antes de escrever código.', content='{"editorial_version":"lc-editorial-pilot-2026.08","sections":[{"title":"Como usar este módulo","body":"Leia buscando entender a relação entre as ideias. O objetivo não é memorizar definições isoladas, mas construir um processo de raciocínio que você reutilizará nos próximos módulos."},{"title":"Checklist antes de programar","items":["Consigo explicar o problema em uma frase?","Sei quais dados entram?","Sei qual resultado precisa sair?","Consigo escrever os passos sem citar uma linguagem?","O problema precisa ser quebrado em partes?","Existe algum padrão conhecido?","Quais detalhes posso esconder por enquanto?","Quais casos normais e limites devo testar?"]},{"title":"Quando voltar ao conteúdo","items":["Se você não consegue prever a saída, volte à modelagem.","Se os passos parecem vagos, refine o algoritmo.","Se o problema parece grande demais, decomponha.","Se a solução está duplicada, procure padrões.","Se há detalhes demais, ajuste o nível de abstração.","Se tudo parece certo mas falha no limite, faça teste de mesa."]}]}'::jsonb where id='196ff65c-0d80-4553-ae6f-5699e9538a81';
update nexora.learning_resources set title='Desafio aplicado — Triagem de atendimento', summary='Atividade integradora para aplicar modelagem, decomposição, padrões, abstração e teste de mesa.', content='{"editorial_version":"lc-editorial-pilot-2026.08","sections":[{"title":"Desafio aplicado — triagem de atendimento","body":"Modele um pequeno sistema de triagem. Cada atendimento possui idade do cliente, tipo do problema e horário de chegada. A regra deve identificar prioridade e produzir uma ordem de atendimento."},{"title":"Sua entrega","items":["Defina claramente entradas e saída.","Decomponha a solução em pelo menos três responsabilidades.","Escreva o algoritmo em linguagem natural ou pseudocódigo.","Indique um padrão de solução que você reconheceu, se houver.","Explique uma abstração usada para reduzir detalhes.","Crie no mínimo um caso normal, um caso-limite e um caso inválido ou excepcional."]},{"title":"Critério de qualidade","body":"A entrega deve ser verificável. Outra pessoa precisa conseguir seguir seus passos, usar os mesmos dados de teste e chegar ao resultado previsto."}]}'::jsonb where id='bf3830b9-2380-4a80-a942-5c618f370958';

commit;
